  "law": {
    "id": "NRS-484B-517",
    "title": "Restricted use of bus and taxicab stands",
    "text": "A person shall not stop, stand or park a vehicle other than a bus in a bus stop, or a taxicab in a taxicab stand, when such stop or stand has been officially designated and appropriately signed, except that the driver of a passenger vehicle may temporarily stop there and for the purpose of and while actually engaged in expeditiously loading or unloading of passengers when such stopping does not interfere with any bus or taxicab waiting to enter or about to enter such zone.",
    "source": "NRS 484B.517"
  }
